import React, { useState, useMemo, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceArea, Label } from 'recharts';
import { Users, Pill, Activity, ArrowLeft, AlertCircle, Calendar, ChevronDown, Search, X, Database, AlertTriangle, HeartPulse, Shuffle, Building2, Loader2 } from 'lucide-react';
import './index.css';

// --- 固定模擬數據 (儀表板使用) ---
const admissionHistory = [
  { id: 'ADM-001', date: '2026/09/10 - 09/30 (本次住院)' },
  { id: 'ADM-002', date: '2025/11/12 - 11/28' }
];

const fullData = Array.from({ length: 21 }, (_, i) => {
  const day = 10 + i;
  return { date: '09/' + day, na: 142 - (i * 0.8) + Math.sin(i), k: 3.6 + (i * 0.12), index: i };
});

const medData = [
  { name: 'FUROSEMIDE (LASIX)', type: 'Na+ Impact', startIdx: 0, endIdx: 15, color: '#3B82F6', impact: '138 -> 128', level: '高度相關' },
  { name: 'LISINOPRIL', type: 'K+ Impact', startIdx: 5, endIdx: 12, color: '#EF4444', impact: '3.5 -> 5.5', level: '中度相關' },
  { name: 'ASPIRIN', type: 'Anti-platelet', startIdx: 0, endIdx: 25, color: '#94A3B8', impact: 'N/A', level: '無明顯相關' },
  { name: 'SPIRONOLACTONE', type: 'K+ Impact', startIdx: 2, endIdx: 18, color: '#94A3B8', impact: '3.6 -> 4.8', level: '無明顯相關' },
  { name: 'KCL', type: 'K+ Impact', startIdx: 8, endIdx: 20, color: '#64748B', impact: '3.8 -> 4.6', level: '預期內治療反應' }
];

const medicationLogs = [
  { name: 'FUROSEMIDE (LASIX)', start: '09/10 08:00', end: '09/25 10:00', dose: ['40 mg IV q12h', '20 mg IV q12h (09/18 減量)'], status: 'PAST' },
  { name: 'LISINOPRIL', start: '09/12 09:00', end: '09/18 10:00', dose: ['5 mg PO QD'], status: 'PAST' },
  { name: 'SPIRONOLACTONE', start: '09/15 08:00', end: '使用中', dose: ['25 mg PO QD'], status: 'ACTIVE' }
];

const mockPatients = [
  {id:'P001', name:'王小明', info:'(男/68)', na:'128', k:'4.5', room:'802-1', status:'危急'}, 
  {id:'P002', name:'李大同', info:'(男/72)', na:'138', k:'4.2', room:'805-2', status:'觀察中'}
];

export default function App() {
  const [view, setView] = useState('overview');
  const [selectedPatient, setSelectedPatient] = useState(null);
  const [windowSize, setWindowSize] = useState(7);
  const [startIndex, setStartIndex] = useState(0);

  // --- 藥物搜尋專用狀態 (API 串接) ---
  const [searchQuery, setSearchQuery] = useState('');
  const [hasResults, setHasResults] = useState(false);
  const [showCategories, setShowCategories] = useState(false);

  // API 資料狀態
  const [searchResults, setSearchResults] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [stats, setStats] = useState({ total: 0, with_reactions: 0 });
  const [systems, setSystems] = useState([]);
  const [selectedSystem, setSelectedSystem] = useState('');

  const visibleData = useMemo(() => fullData.slice(startIndex, startIndex + windowSize), [startIndex, windowSize]);

  // 載入初始統計數據與分類 (當切換到 repository 視圖時)
  useEffect(() => {
    if (view === 'repository') {
      fetch('http://localhost:5000/api/drugs/stats')
        .then(res => res.json())
        .then(data => setStats(data))
        .catch(err => console.error("無法載入統計:", err));

      fetch('http://localhost:5000/api/drugs/systems')
        .then(res => res.json())
        .then(data => setSystems(data))
        .catch(err => console.error("無法載入系統分類:", err));
    }
  }, [view]);

  // 執行搜尋 API
  const performSearch = async (query, system = '') => {
    setIsLoading(true);
    setHasResults(true);
    try {
      let url = "http://localhost:5000/api/drugs/search?q=" + encodeURIComponent(query);
      if (system) {
        url += "&system=" + encodeURIComponent(system);
      }

      const response = await fetch(url);
      if (!response.ok) throw new Error("網路請求失敗");

      const data = await response.json();
      setSearchResults(data);
    } catch (error) {
      console.error("搜尋發生錯誤:", error);
      alert("無法連線到資料庫，請確認 Flask 伺服器 (Port 5000) 是否已啟動！");
      setHasResults(false);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSystemClick = (sys) => {
    const newSys = selectedSystem === sys ? '' : sys;
    setSelectedSystem(newSys);
    performSearch(searchQuery, newSys);
  };

  // 安全的 className 組合
  const repoContainerClass = "w-full flex flex-col items-center transition-all duration-500 ease-in-out " + (hasResults ? "pt-8 pb-6 border-b border-slate-200 bg-white sticky top-0 z-50 shadow-sm" : "pt-[20vh]");
  const logoContainerClass = "text-center transition-all duration-500 " + (hasResults ? "mb-4 flex items-center gap-3" : "mb-8");
  const logoTextClass = "font-bold text-[#0f4c81] flex items-center justify-center gap-2 " + (hasResults ? "text-2xl" : "text-4xl");

  if (view === 'repository') {
    return (
      <div className="flex h-screen bg-white font-sans text-left">
        <div className="w-64 bg-slate-50 border-r p-6 flex flex-col shadow-sm">
          <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic"><Activity /> ADR PRO</div>
          <button onClick={() => setView('overview')} className="flex items-center gap-3 p-4 text-slate-400 hover:bg-slate-100 rounded-2xl font-bold w-full mb-4 transition-all">
            <Users size={18} /> 病人總覽
          </button>
          <button className="flex items-center gap-3 p-4 bg-blue-600 text-white rounded-2xl font-bold w-full shadow-lg">
            <Pill size={18} /> 藥物查詢
          </button>
        </div>

        <div className="flex-1 overflow-y-auto relative bg-[#f8fafc]">
          <div className={repoContainerClass}>
            <div className={logoContainerClass}>
              <h1 className={logoTextClass}>
                <Building2 className="text-[#0f4c81]" size={hasResults ? 28 : 40} /> 
                台北榮總藥物查詢
              </h1>
              {!hasResults && <p className="text-slate-500 text-lg mt-3 font-bold tracking-widest">臨床醫師專用搜尋引擎</p>}
            </div>

            <div className="w-full max-w-2xl px-6">
              <div className="flex items-center bg-white border border-slate-200 rounded-full px-6 py-3 shadow-lg hover:shadow-xl transition-shadow">
                <Search className="text-slate-400 mr-3" size={22} />
                <input 
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter') performSearch(searchQuery, selectedSystem); }}
                  className="flex-1 outline-none text-xl text-slate-800 bg-transparent"
                  placeholder="輸入藥名或適應症，按下 Enter 搜尋..."
                />
                {searchQuery && (
                  <X className="text-slate-400 cursor-pointer ml-3 hover:text-slate-600" size={24} onClick={() => {
                    setSearchQuery(''); 
                    setSelectedSystem('');
                    setHasResults(false);
                    setSearchResults([]);
                  }} />
                )}
              </div>
            </div>

            <div className="flex flex-wrap justify-center gap-4 mt-8 px-6 font-bold text-sm">
              <button onClick={() => performSearch('', '')} className="flex items-center gap-2 px-5 py-2 rounded-full border border-[#0f4c81] text-[#0f4c81] hover:bg-[#0f4c81] hover:text-white transition-colors group bg-white">
                <Database size={18} /> 收錄藥物
                <span className="bg-[#0f4c81] text-white px-2 py-0.5 rounded-full text-xs ml-1 group-hover:bg-white group-hover:text-[#0f4c81] transition-colors">{stats.total || '-'}</span>
              </button>
              <button onClick={() => performSearch('reactions', '')} className="flex items-center gap-2 px-5 py-2 rounded-full border border-rose-600 text-rose-600 hover:bg-rose-600 hover:text-white transition-colors group bg-white">
                <AlertTriangle size={18} /> 不良反應藥物
                <span className="bg-rose-600 text-white px-2 py-0.5 rounded-full text-xs ml-1 group-hover:bg-white group-hover:text-rose-600 transition-colors">{stats.with_reactions || '-'}</span>
              </button>
              <button onClick={() => setShowCategories(!showCategories)} className="flex items-center gap-2 px-5 py-2 rounded-full border border-emerald-600 text-emerald-600 hover:bg-emerald-600 hover:text-white transition-colors bg-white">
                <HeartPulse size={18} /> 身體反應分類
                <ChevronDown size={16} className={"transition-transform " + (showCategories ? "rotate-180" : "")} />
              </button>
            </div>

            {showCategories && (
              <div className="mt-6 p-6 bg-slate-50 rounded-2xl border border-slate-200 max-w-3xl w-full mx-6 text-center">
                 <h6 className="text-slate-500 mb-4 font-bold">請選擇受影響的身體系統進行過濾：</h6>
                 <div className="flex flex-wrap justify-center gap-2">
                   {systems.map(sys => (
                     <span 
                       key={sys} 
                       onClick={() => handleSystemClick(sys)}
                       className={"px-4 py-1.5 border rounded-full text-sm font-bold cursor-pointer transition-all hover:shadow-sm " + (selectedSystem === sys ? "bg-emerald-600 text-white border-emerald-600" : "bg-white text-slate-600 hover:border-emerald-400")}
                     >
                       {sys}
                     </span>
                   ))}
                 </div>
              </div>
            )}
          </div>

          {hasResults && (
            <div className="max-w-5xl mx-auto p-8 fade-in">
              <div className="flex justify-between items-center border-b pb-4 mb-6">
                <div className="text-xl font-bold text-slate-800">
                  {selectedSystem ? "分類搜尋: " + selectedSystem : (searchQuery ? '搜尋結果: "' + searchQuery + '"' : "所有藥物列表")} 
                  <span className="text-slate-400 text-base ml-2">({searchResults.length} 筆)</span>
                </div>
                <div className="flex items-center gap-4 text-sm font-bold text-slate-500">
                  <span className="bg-slate-200 px-3 py-1 rounded-full">資料庫: 2024.11</span>
                  <button onClick={() => alert('此功能目前建置中！')} className="flex items-center gap-1 hover:text-blue-600 transition-colors">
                    <Shuffle size={14}/> 查詢交互作用?
                  </button>
                </div>
              </div>

              {isLoading ? (
                <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                  <Loader2 className="animate-spin mb-4 text-blue-500" size={40} />
                  <p className="font-bold text-lg">正在從資料庫撈取資料...</p>
                </div>
              ) : searchResults.length > 0 ? (
                <div className="bg-white border rounded-2xl overflow-hidden shadow-sm">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-slate-500 text-sm border-b">
                      <tr>
                        <th className="p-5 font-bold w-32">藥碼</th>
                        <th className="p-5 font-bold">藥物名稱 (Drug Name)</th>
                        <th className="p-5 font-bold hidden md:table-cell">適應症</th>
                        <th className="p-5 font-bold text-right">警示狀態</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {searchResults.map((drug, i) => (
                        <tr key={i} className="hover:bg-blue-50 transition-colors cursor-pointer group" onClick={() => alert('點擊可展開詳細資料 (前端保留擴充)')}>
                          <td className="p-5 font-mono text-slate-500 font-bold">{drug.id || "N/A"}</td>
                          <td className="p-5">
                            <div className="font-black text-[#0f4c81] text-lg">{drug.name}</div>
                            <div className="text-xs text-slate-400 font-bold mt-1">{drug.category || "未分類"}</div>
                          </td>
                          <td className="p-5 text-slate-600 text-sm hidden md:table-cell max-w-xs truncate">
                            {drug.indications ? drug.indications.join(', ') : "無資料"}
                          </td>
                          <td className="p-5 text-right">
                            {drug.side_effects && (drug.side_effects.severity === 'Severe' || drug.side_effects.severity === 'Moderate') ? (
                              <span className="bg-rose-100 text-rose-700 px-4 py-1.5 rounded-full text-xs font-black tracking-widest border border-rose-200">風險警示</span>
                            ) : (
                              <span className="bg-emerald-100 text-emerald-700 px-4 py-1.5 rounded-full text-xs font-black tracking-widest border border-emerald-200">收錄中</span>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <div className="text-center py-20 text-slate-400 font-bold text-xl">
                  找不到符合的藥物資料
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    );
  }

  // --- 2. Dashboard View ---
  if (view === 'dashboard') {
    return (
      <div className="flex h-screen bg-[#F8FAFC] font-sans text-left">
        <div className="w-64 bg-white border-r p-6 flex flex-col shadow-sm">
          <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic font-sans"><Activity /> ADR PRO</div>
          <button onClick={() => setView('overview')} className="flex items-center gap-3 p-4 bg-blue-600 text-white rounded-2xl font-bold shadow-lg w-full mb-4 transition-all"><Users size={18} /> 病人總覽</button>
          <button onClick={() => {setView('repository'); setHasResults(false); setSearchQuery(''); setSelectedSystem('');}} className="flex items-center gap-3 p-4 text-slate-400 hover:bg-slate-50 rounded-2xl font-bold w-full transition-all"><Pill size={18} /> 藥物查詢</button>
        </div>

        <div className="flex-1 overflow-y-auto p-8">
          <div className="flex justify-between items-center mb-8">
            <div className="flex items-center gap-4">
              <button onClick={() => setView('overview')} className="p-3 bg-white border rounded-xl hover:text-blue-600 shadow-sm transition-all"><ArrowLeft size={18} /></button>
              <div className="bg-white px-6 py-3 rounded-2xl border flex items-center gap-3 shadow-sm font-bold text-slate-700 text-sm italic">
                {admissionHistory[0].date} <ChevronDown size={14} className="text-slate-300" />
              </div>
            </div>
            <div className="flex gap-2">
              {[3, 7, 14].map(d => (
                <button key={d} onClick={() => { setWindowSize(d); setStartIndex(0); }} className={windowSize === d ? "px-6 py-2 rounded-lg bg-blue-600 text-white font-bold text-xs" : "px-6 py-2 bg-white text-slate-400 border font-bold text-xs hover:bg-slate-50 transition-all"}>{d}D</button>
              ))}
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] p-10 border border-slate-100 shadow-sm mb-8">
            <div className="h-72 w-full mb-6">
              <ResponsiveContainer>
                <LineChart data={visibleData} margin={{ left: 10, right: 10 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#F1F5F9" />
                  <XAxis dataKey="date" axisLine={false} tickLine={false} tick={{fill: '#94A3B8', fontSize: 11, fontWeight: 'bold'}} />
                  <YAxis yAxisId="na" domain={[120, 160]} ticks={[120, 130, 140, 150, 160]} axisLine={false} tickLine={false} tick={{fill: '#F97316', fontSize: 10, fontWeight: 'bold'}} width={40} />
                  <YAxis yAxisId="k" orientation="right" domain={[2, 8]} ticks={[2, 4, 6, 8]} axisLine={false} tickLine={false} tick={{fill: '#6366F1', fontSize: 10, fontWeight: 'bold'}} width={40} />
                  <Tooltip contentStyle={{ borderRadius: '15px', border: 'none', boxShadow: '0 10px 20px rgba(0,0,0,0.05)', fontWeight: 'bold' }} />

                  <ReferenceArea yAxisId="na" y1={135} y2={145} fill="#F97316" fillOpacity={0.05}>
                    <Label value="Na Range (135-145)" position="insideTopLeft" fill="#F97316" fontSize={10} fontWeight="bold" />
                  </ReferenceArea>
                  <ReferenceArea yAxisId="k" y1={3.5} y2={5.0} fill="#6366F1" fillOpacity={0.05}>
                    <Label value="K Range (3.5-5.0)" position="insideBottomRight" fill="#6366F1" fontSize={10} fontWeight="bold" />
                  </ReferenceArea>

                  <Line yAxisId="na" type="monotone" dataKey="na" stroke="#F97316" strokeWidth={5} dot={{r: 6, fill: '#F97316', strokeWidth: 3, stroke: '#fff'}} isAnimationActive={false} />
                  <Line yAxisId="k" type="monotone" dataKey="k" stroke="#6366F1" strokeWidth={5} dot={{r: 6, fill: '#6366F1', strokeWidth: 3, stroke: '#fff'}} isAnimationActive={false} />
                </LineChart>
              </ResponsiveContainer>
            </div>

            <div className="px-10 mb-12">
              <input type="range" min="0" max={21 - windowSize} value={startIndex} onChange={(e) => setStartIndex(parseInt(e.target.value))} className="w-full h-2 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-blue-600" />
              <div className="flex justify-between text-[10px] font-black text-slate-400 mt-4 uppercase">
                <span>住院開始 (09/10)</span>
                <span className="text-blue-600 font-bold bg-blue-50 px-4 py-1.5 rounded-full border border-blue-100 italic tracking-tight">平移檢視: {visibleData[0]?.date} - {visibleData[windowSize-1]?.date}</span>
                <span>住院結束 (09/30)</span>
              </div>
            </div>

            <div className="space-y-4 pt-10 border-t border-slate-100">
              {medData.map((med, i) => {
                const viewStart = startIndex;
                const viewEnd = startIndex + windowSize - 1;
                const left = Math.max(0, ((med.startIdx - viewStart) / windowSize) * 100);
                const right = Math.min(100, ((med.endIdx - viewStart + 1) / windowSize) * 100);
                const width = Math.max(0, right - left);

                return (
                  <div key={i} className="flex items-center">
                    <div className="w-48 text-left pr-4">
                      <p className="text-[11px] font-black text-slate-700 italic tracking-tighter">{med.name}</p>
                      <p className="text-[9px] text-slate-400 font-bold uppercase">{med.type}</p>
                    </div>
                    <div className="flex-1 h-10 bg-slate-50 rounded-xl relative overflow-hidden border border-slate-100 shadow-inner">
                      {width > 0 && (
                        <div className="absolute h-full opacity-80 rounded-lg shadow-sm flex items-center px-4 transition-all duration-75" style={{ left: left + '%', width: width + '%', backgroundColor: med.color }}>
                          <span className="text-[8px] text-white font-black uppercase opacity-75">USAGE</span>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="bg-white rounded-[2.5rem] shadow-sm border p-10 mb-8 text-left">
             <div className="flex items-center gap-2 mb-8 font-black text-slate-700 italic border-l-4 border-blue-600 pl-4 uppercase">實際用藥全紀錄 (住院詳細明細)</div>
             <table className="w-full text-left text-xs">
                <thead className="text-slate-400 border-b">
                  <tr><th className="pb-4">藥物名稱</th><th className="pb-4">開始給藥</th><th className="pb-4">停止給藥</th><th className="pb-4 text-center">劑量變動歷程</th><th className="pb-4 text-right">狀態</th></tr>
                </thead>
                <tbody className="divide-y">
                  {medicationLogs.map((log, i) => (
                    <tr key={i} className="hover:bg-slate-50 transition-all">
                      <td className="py-6 font-black italic text-slate-700 uppercase tracking-tighter">{log.name}</td>
                      <td className="py-6 text-slate-400 font-medium font-mono">{log.start}</td>
                      <td className="py-6 text-slate-400 font-medium font-mono">{log.end}</td>
                      <td className="py-6 font-bold text-slate-600 text-center">{log.dose.map((d, di) => <div key={di} className="flex items-center justify-center gap-2 font-sans"><div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div>{d}</div>)}</td>
                      <td className="py-6 text-right font-black uppercase text-[10px]"><span className={log.status === 'ACTIVE' ? "text-emerald-500 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100" : "text-slate-400 bg-slate-100 px-3 py-1 rounded-full border border-slate-200"}>{log.status}</span></td>
                    </tr>
                  ))}
                </tbody>
             </table>
          </div>

          <div className="bg-white rounded-[2.5rem] shadow-sm border border-slate-100 overflow-hidden mb-12 text-left">
            <div className="bg-rose-50/50 p-8 border-b flex items-center gap-3"><AlertCircle className="text-rose-500" size={24} /><h2 className="text-rose-900 font-black italic text-xl uppercase tracking-tighter">ADR 關聯分析結果</h2></div>
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 text-slate-400 text-[10px] font-black uppercase tracking-widest">
                <tr><th className="p-8">臨床肇因藥物</th><th className="p-8">影響維度</th><th className="p-8 text-center tracking-tighter">檢驗值變化</th><th className="p-8 text-right">智慧判定結論</th></tr>
              </thead>
              <tbody className="divide-y">
                {medData.map((med, i) => (
                  <tr key={i} className="hover:bg-slate-50 transition-all">
                    <td className="p-8 font-black text-slate-700 italic text-lg tracking-tighter">{med.name} {med.level.includes('高') && <span className="bg-rose-100 text-rose-500 text-[8px] px-2 py-0.5 rounded font-black ml-2 uppercase">Critical</span>}</td>
                    <td className="p-8 text-slate-400 font-bold tracking-tighter uppercase">{med.type}</td>
                    <td className="p-8 font-mono font-black text-2xl italic text-center text-rose-500">{med.impact}</td>
                    <td className="p-8 text-right font-black"><span className="px-10 py-4 rounded-3xl text-xs font-black uppercase text-white shadow-xl inline-block" style={{ backgroundColor: med.level.includes('高') ? '#F43F5E' : med.level.includes('中') ? '#F97316' : '#94A3B8' }}>{med.level}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    );
  }

  // --- 3. Overview View ---
  return (
    <div className="flex h-screen bg-[#F8FAFC] font-sans text-left">
      <div className="w-64 bg-white border-r p-6 flex flex-col shadow-sm">
        <div className="flex items-center gap-2 text-blue-600 font-bold mb-10 text-xl italic tracking-tighter"><Activity strokeWidth={3}/> ADR PRO</div>
        <button className="flex items-center gap-3 p-4 bg-blue-600 text-white rounded-2xl font-bold shadow-lg shadow-blue-100 mb-4 transition-all"><Users size={18} /> 病人總覽</button>
        <button onClick={() => {setView('repository'); setHasResults(false); setSearchQuery(''); setSelectedSystem(''); setSearchResults([]);}} className="flex items-center gap-3 p-4 text-slate-400 hover:bg-slate-50 rounded-2xl font-bold transition-all"><Pill size={18} /> 藥物查詢</button>
      </div>

      <div className="flex-1 p-12 overflow-y-auto">
        <h1 className="text-2xl font-black italic text-slate-800 mb-8 border-b-[3px] border-blue-600 inline-block pb-1 uppercase tracking-tight">Patient Admission Records</h1>
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden max-w-6xl">
          <table className="w-full text-left">
            <thead className="bg-white border-b border-slate-100 text-slate-400 text-[11px] font-bold uppercase tracking-widest">
              <tr><th className="py-6 px-8">病歷 ID</th><th className="py-6 px-8">病患</th><th className="py-6 px-8 text-center">目前房號</th><th className="py-6 px-8 text-center">最新 Na+ / K+</th><th className="py-6 px-8 text-right pr-12">監測狀態</th></tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {mockPatients.map(p => (
                <tr key={p.id} onClick={() => { setSelectedPatient(p); setView('dashboard'); }} className="hover:bg-slate-50 transition-all cursor-pointer group">
                  <td className="py-6 px-8 font-black text-blue-600 text-sm tracking-tight">{p.id}</td>
                  <td className="py-6 px-8 text-slate-700 font-bold text-sm">{p.name} <span className="text-slate-400 font-normal ml-1">{p.info}</span></td>
                  <td className="py-6 px-8 text-slate-500 font-medium text-sm text-center">{p.room}</td>
                  <td className="py-6 px-8 font-sans font-bold text-base text-center">
                    <span className={p.status === '危急' ? "text-rose-500 underline decoration-rose-500 underline-offset-4 font-black" : "text-slate-700 font-black"}>{p.na}</span> 
                    <span className="text-slate-400 font-normal mx-1">/</span> 
                    <span className="text-slate-700 font-black">{p.k}</span>
                  </td>
                  <td className="py-6 px-8 text-right pr-12">
                    <span className={p.status === '危急' ? "bg-rose-100 text-rose-500 px-4 py-1.5 rounded-full text-[11px] font-bold tracking-widest border border-rose-50" : "bg-[#FEF3C7] text-[#D97706] px-4 py-1.5 rounded-full text-[11px] font-bold tracking-widest border border-yellow-50"}>{p.status}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
